import { Component, input, output, signal } from '@angular/core';
import { CommonModule } from '@angular/common';

export interface AccordionItem {
  id: string;
  title: string;
  content: string;
  isOpen?: boolean;
  disabled?: boolean;
}

@Component({
  selector: 'app-accordion',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './accordion.component.html',
  styleUrl: './accordion.component.css'
})
export class AccordionComponent {
  // Inputs
  items = input.required<AccordionItem[]>();
  allowMultiple = input<boolean>(false);
  animated = input<boolean>(true);

  // Outputs
  itemToggled = output<AccordionItem>();

  // State
  openItems = signal<Set<string>>(new Set());

  ngOnInit() {
    // Initialize open items
    const initialOpenItems = this.items()
      .filter(item => item.isOpen)
      .map(item => item.id);

    this.openItems.set(new Set(initialOpenItems));
  }

  toggle(item: AccordionItem) {
    if (item.disabled) {
      return;
    }

    const openItems = new Set(this.openItems());

    if (openItems.has(item.id)) {
      // Close the item
      openItems.delete(item.id);
    } else {
      // Open the item
      if (!this.allowMultiple()) {
        // Close all other items
        openItems.clear();
      }
      openItems.add(item.id);
    }

    this.openItems.set(openItems);
    this.itemToggled.emit(item);
  }

  isOpen(item: AccordionItem): boolean {
    return this.openItems().has(item.id);
  }
}

import { Component, signal, effect } from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { DropdownComponent, DropdownItem } from './components/ui/dropdown/dropdown.component';
import { MultiSelectComponent, MultiSelectItem } from './components/ui/multiselect/multiselect.component';
import { ModalComponent } from './components/ui/modal/modal.component';
import { AccordionComponent, AccordionItem } from './components/ui/accordion/accordion.component';
import { TooltipComponent } from './components/ui/tooltip/tooltip.component';
import { TabsComponent, TabItem } from './components/ui/tabs/tabs.component';
import { ToastContainerComponent } from './components/ui/toast/toast-container.component';
import { Toast } from './components/ui/toast/toast.component';

interface ColorConfig {
  name: string;
  variable: string;
  defaultLight: string;
  defaultDark: string;
}

@Component({
  selector: 'app-root',
  imports: [
    RouterOutlet,
    DropdownComponent,
    MultiSelectComponent,
    ModalComponent,
    AccordionComponent,
    TooltipComponent,
    TabsComponent,
    ToastContainerComponent
  ],
  templateUrl: './app.html',
  styleUrl: './app.css'
})
export class App {
  protected readonly title = signal('loan-ui');

  // Demo data for components
  protected dropdownItems = signal<DropdownItem[]>([
    { label: 'Dashboard', value: 'dashboard' },
    { label: 'Settings', value: 'settings' },
    { label: 'Earnings', value: 'earnings' },
    { label: 'Sign out', value: 'signout', divider: true },
  ]);

  protected multiSelectItems = signal<MultiSelectItem[]>([
    { label: 'React', value: 'react' },
    { label: 'Angular', value: 'angular' },
    { label: 'Vue', value: 'vue' },
    { label: 'Svelte', value: 'svelte' },
    { label: 'Next.js', value: 'nextjs' },
  ]);

  protected accordionItems = signal<AccordionItem[]>([
    {
      id: '1',
      title: '¿Qué es Flowbite?',
      content: 'Flowbite es una biblioteca de componentes de código abierto construida con Tailwind CSS con elementos interactivos como dropdowns, modals, navbars, y más.',
      isOpen: true
    },
    {
      id: '2',
      title: '¿Es gratis usar Flowbite?',
      content: 'Sí, Flowbite es 100% gratuito y de código abierto bajo la licencia MIT. Puedes usarlo en proyectos personales y comerciales.'
    },
    {
      id: '3',
      title: '¿Qué tecnologías soporta?',
      content: 'Flowbite funciona con Tailwind CSS v3.x y es compatible con React, Vue, Angular, Svelte y vanilla JavaScript.'
    }
  ]);

  protected tabItems = signal<TabItem[]>([
    {
      id: 'profile',
      label: 'Perfil',
      content: 'Información del perfil del usuario. Aquí puedes ver y editar tu información personal.',
      icon: '👤'
    },
    {
      id: 'dashboard',
      label: 'Dashboard',
      content: 'Panel de control con estadísticas y métricas importantes de tu cuenta.'
    },
    {
      id: 'settings',
      label: 'Configuración',
      content: 'Ajusta las preferencias y configuraciones de tu cuenta.'
    },
    {
      id: 'disabled',
      label: 'Deshabilitado',
      content: '',
      disabled: true
    }
  ]);

  protected toasts = signal<Toast[]>([
    {
      id: '1',
      type: 'success',
      title: 'Success!',
      message: 'Tu operación se completó correctamente',
      duration: 5000,
      dismissible: true
    }
  ]);

  protected isModalOpenLight = signal(false);
  protected isModalOpenDark = signal(false);
  protected selectedDropdownItem = signal<DropdownItem | null>(null);
  protected selectedMultiItems = signal<MultiSelectItem[]>([]);

  // Configuración de colores editables
  protected colors: ColorConfig[] = [
    { name: 'Primary', variable: 'primary', defaultLight: '#1d4ed8', defaultDark: '#2563eb' },
    { name: 'Primary Hover', variable: 'primary-hover', defaultLight: '#1e40af', defaultDark: '#1d4ed8' },
    { name: 'Success', variable: 'success', defaultLight: '#15803d', defaultDark: '#16a34a' },
    { name: 'Success Hover', variable: 'success-hover', defaultLight: '#166534', defaultDark: '#15803d' },
    { name: 'Error', variable: 'error', defaultLight: '#b91c1c', defaultDark: '#dc2626' },
    { name: 'Error Hover', variable: 'error-hover', defaultLight: '#991b1b', defaultDark: '#b91c1c' },
    { name: 'Warning', variable: 'warning', defaultLight: '#eab308', defaultDark: '#facc15' },
    { name: 'Warning Hover', variable: 'warning-hover', defaultLight: '#ca8a04', defaultDark: '#eab308' },
    { name: 'Info', variable: 'info', defaultLight: '#0891b2', defaultDark: '#06b6d4' },
    { name: 'Info Hover', variable: 'info-hover', defaultLight: '#0e7490', defaultDark: '#0891b2' },
  ];

  protected currentLightColors = signal<Record<string, string>>({});
  protected currentDarkColors = signal<Record<string, string>>({});

  constructor() {
    // Inicializar colores
    const lightColors: Record<string, string> = {};
    const darkColors: Record<string, string> = {};

    this.colors.forEach(color => {
      lightColors[color.variable] = color.defaultLight;
      darkColors[color.variable] = color.defaultDark;
    });

    this.currentLightColors.set(lightColors);
    this.currentDarkColors.set(darkColors);

    // Aplicar colores light mode por defecto
    this.applyLightColors();
  }

  protected onColorChange(variable: string, value: string, isDark: boolean) {
    if (isDark) {
      const colors = { ...this.currentDarkColors() };
      colors[variable] = value;
      this.currentDarkColors.set(colors);
      this.applyDarkColors();
    } else {
      const colors = { ...this.currentLightColors() };
      colors[variable] = value;
      this.currentLightColors.set(colors);
      this.applyLightColors();
    }
  }

  protected resetColors() {
    const lightColors: Record<string, string> = {};
    const darkColors: Record<string, string> = {};

    this.colors.forEach(color => {
      lightColors[color.variable] = color.defaultLight;
      darkColors[color.variable] = color.defaultDark;
    });

    this.currentLightColors.set(lightColors);
    this.currentDarkColors.set(darkColors);

    this.applyLightColors();
    this.applyDarkColors();
  }

  private applyLightColors() {
    const root = document.documentElement;
    const colors = this.currentLightColors();

    Object.entries(colors).forEach(([variable, value]) => {
      root.style.setProperty(`--color-${variable}`, value);
    });
  }

  private applyDarkColors() {
    // Para dark mode, necesitamos aplicar las variables dentro de .dark
    const colors = this.currentDarkColors();
    const styleId = 'dynamic-dark-colors';
    let styleElement = document.getElementById(styleId) as HTMLStyleElement;

    if (!styleElement) {
      styleElement = document.createElement('style');
      styleElement.id = styleId;
      document.head.appendChild(styleElement);
    }

    const darkStyles = Object.entries(colors)
      .map(([variable, value]) => `--color-${variable}: ${value};`)
      .join('\n  ');

    styleElement.textContent = `.dark {\n  ${darkStyles}\n}`;
  }

  // Component event handlers
  protected onDropdownChange(item: DropdownItem) {
    this.selectedDropdownItem.set(item);
    console.log('Dropdown selected:', item);
  }

  protected onMultiSelectChange(items: MultiSelectItem[]) {
    this.selectedMultiItems.set(items);
    console.log('MultiSelect changed:', items);
  }

  protected openModalLight() {
    this.isModalOpenLight.set(true);
  }

  protected closeModalLight() {
    this.isModalOpenLight.set(false);
  }

  protected openModalDark() {
    this.isModalOpenDark.set(true);
  }

  protected closeModalDark() {
    this.isModalOpenDark.set(false);
  }

  protected onAccordionToggle(item: AccordionItem) {
    console.log('Accordion toggled:', item);
  }

  protected onTabChange(tab: TabItem) {
    console.log('Tab changed:', tab);
  }

  protected showToast(type: 'success' | 'error' | 'warning' | 'info') {
    const messages = {
      success: { title: 'Éxito!', message: 'La operación se completó correctamente' },
      error: { title: 'Error!', message: 'Algo salió mal. Por favor intenta de nuevo' },
      warning: { title: 'Advertencia!', message: 'Ten cuidado con esta acción' },
      info: { title: 'Información', message: 'Aquí hay información importante' }
    };

    const newToast: Toast = {
      id: Date.now().toString(),
      type,
      ...messages[type],
      duration: 5000,
      dismissible: true
    };

    this.toasts.update(toasts => [...toasts, newToast]);
  }

  protected dismissToast(id: string) {
    this.toasts.update(toasts => toasts.filter(t => t.id !== id));
  }
}

import { Component, input, output, signal, computed, HostListener, ElementRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

export interface DropdownItem {
  label: string;
  value: any;
  icon?: string;
  disabled?: boolean;
  divider?: boolean;
  group?: string;
}

@Component({
  selector: 'app-dropdown',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './dropdown.component.html',
  styleUrl: './dropdown.component.css'
})
export class DropdownComponent {
  // Inputs
  items = input.required<DropdownItem[]>();
  placeholder = input<string>('Select an option');
  disabled = input<boolean>(false);
  position = input<'bottom' | 'top' | 'auto'>('auto');
  variant = input<'primary' | 'secondary' | 'outline'>('outline');
  size = input<'sm' | 'md' | 'lg'>('md');
  searchable = input<boolean>(false);
  clearable = input<boolean>(false);
  loading = input<boolean>(false);

  // Outputs
  selectionChange = output<DropdownItem>();
  searchChange = output<string>();

  // State
  isOpen = signal(false);
  selectedItem = signal<DropdownItem | null>(null);
  searchQuery = signal('');
  highlightedIndex = signal(-1);

  // Computed
  buttonClass = computed(() => {
    const base = 'btn dropdown-toggle';
    const variantClass = this.variant() === 'outline' ? 'btn-outline-primary' : `btn-${this.variant()}`;
    const sizeClass = `btn-${this.size()}`;
    const openClass = this.isOpen() ? 'active' : '';
    return `${base} ${variantClass} ${sizeClass} ${openClass}`;
  });

  filteredItems = computed(() => {
    const query = this.searchQuery().toLowerCase().trim();
    if (!query) return this.items();

    return this.items().filter(item => {
      if (item.divider) return false;
      return item.label.toLowerCase().includes(query);
    });
  });

  constructor(private elementRef: ElementRef) {}

  // Click outside to close
  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent) {
    const clickedInside = this.elementRef.nativeElement.contains(event.target);
    if (!clickedInside && this.isOpen()) {
      this.close();
    }
  }

  // Keyboard navigation
  @HostListener('document:keydown', ['$event'])
  onKeyDown(event: KeyboardEvent) {
    if (!this.isOpen()) {
      // Open dropdown with Enter or Space
      if ((event.key === 'Enter' || event.key === ' ') &&
          this.elementRef.nativeElement.contains(event.target)) {
        event.preventDefault();
        this.open();
      }
      return;
    }

    switch (event.key) {
      case 'Escape':
        event.preventDefault();
        this.close();
        break;

      case 'ArrowDown':
        event.preventDefault();
        this.highlightNext();
        break;

      case 'ArrowUp':
        event.preventDefault();
        this.highlightPrevious();
        break;

      case 'Enter':
        event.preventDefault();
        this.selectHighlighted();
        break;

      case 'Home':
        event.preventDefault();
        this.highlightFirst();
        break;

      case 'End':
        event.preventDefault();
        this.highlightLast();
        break;
    }
  }

  toggle() {
    if (this.disabled() || this.loading()) return;
    this.isOpen() ? this.close() : this.open();
  }

  open() {
    if (this.disabled() || this.loading()) return;
    this.isOpen.set(true);
    this.highlightedIndex.set(-1);

    // Focus search input if searchable
    if (this.searchable()) {
      setTimeout(() => {
        const searchInput = this.elementRef.nativeElement.querySelector('.dropdown-search');
        searchInput?.focus();
      }, 50);
    }
  }

  close() {
    this.isOpen.set(false);
    this.searchQuery.set('');
    this.highlightedIndex.set(-1);
  }

  selectItem(item: DropdownItem) {
    if (item.disabled || item.divider) return;

    this.selectedItem.set(item);
    this.selectionChange.emit(item);
    this.close();
  }

  clearSelection(event: Event) {
    event.stopPropagation();
    this.selectedItem.set(null);
    this.selectionChange.emit(null as any);
  }

  onSearchInput(event: Event) {
    const value = (event.target as HTMLInputElement).value;
    this.searchQuery.set(value);
    this.searchChange.emit(value);
    this.highlightedIndex.set(-1);
  }

  // Keyboard navigation helpers
  private highlightNext() {
    const items = this.getSelectableItems();
    if (items.length === 0) return;

    let newIndex = this.highlightedIndex() + 1;
    if (newIndex >= items.length) newIndex = 0;

    this.highlightedIndex.set(newIndex);
    this.scrollToHighlighted();
  }

  private highlightPrevious() {
    const items = this.getSelectableItems();
    if (items.length === 0) return;

    let newIndex = this.highlightedIndex() - 1;
    if (newIndex < 0) newIndex = items.length - 1;

    this.highlightedIndex.set(newIndex);
    this.scrollToHighlighted();
  }

  private highlightFirst() {
    const items = this.getSelectableItems();
    if (items.length > 0) {
      this.highlightedIndex.set(0);
      this.scrollToHighlighted();
    }
  }

  private highlightLast() {
    const items = this.getSelectableItems();
    if (items.length > 0) {
      this.highlightedIndex.set(items.length - 1);
      this.scrollToHighlighted();
    }
  }

  private selectHighlighted() {
    const items = this.getSelectableItems();
    const index = this.highlightedIndex();

    if (index >= 0 && index < items.length) {
      this.selectItem(items[index]);
    }
  }

  private getSelectableItems(): DropdownItem[] {
    return this.filteredItems().filter(item => !item.disabled && !item.divider);
  }

  private scrollToHighlighted() {
    setTimeout(() => {
      const highlighted = this.elementRef.nativeElement.querySelector('.dropdown-item.highlighted');
      highlighted?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }, 0);
  }

  isItemHighlighted(item: DropdownItem): boolean {
    const items = this.getSelectableItems();
    const itemIndex = items.indexOf(item);
    return itemIndex === this.highlightedIndex();
  }

  isItemSelected(item: DropdownItem): boolean {
    return this.selectedItem()?.value === item.value;
  }
}

import { Component, input, output, signal, computed, HostListener, ElementRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

export interface MultiSelectItem {
  label: string;
  value: any;
  icon?: string;
  disabled?: boolean;
  group?: string;
}

@Component({
  selector: 'app-multiselect',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './multiselect.component.html',
  styleUrl: './multiselect.component.css'
})
export class MultiSelectComponent {
  // Inputs
  items = input.required<MultiSelectItem[]>();
  placeholder = input<string>('Select options');
  disabled = input<boolean>(false);
  maxSelections = input<number | null>(null);
  showCheckboxes = input<boolean>(true);
  showSelectAll = input<boolean>(true);
  searchable = input<boolean>(true);
  showBadges = input<boolean>(true);
  variant = input<'primary' | 'secondary' | 'outline'>('outline');
  size = input<'sm' | 'md' | 'lg'>('md');
  position = input<'bottom' | 'top' | 'auto'>('auto');
  loading = input<boolean>(false);
  clearable = input<boolean>(true);

  // Outputs
  selectionChange = output<MultiSelectItem[]>();
  searchChange = output<string>();

  // State
  isOpen = signal(false);
  selectedItems = signal<MultiSelectItem[]>([]);
  searchQuery = signal('');
  highlightedIndex = signal(-1);

  // Computed
  buttonClass = computed(() => {
    const base = 'btn multiselect-toggle';
    const variantClass = this.variant() === 'outline' ? 'btn-outline-primary' : `btn-${this.variant()}`;
    const sizeClass = `btn-${this.size()}`;
    const openClass = this.isOpen() ? 'active' : '';
    return `${base} ${variantClass} ${sizeClass} ${openClass}`;
  });

  filteredItems = computed(() => {
    const query = this.searchQuery().toLowerCase().trim();
    if (!query) return this.items();

    return this.items().filter(item => {
      return item.label.toLowerCase().includes(query);
    });
  });

  displayText = computed(() => {
    const count = this.selectedItems().length;
    if (count === 0) {
      return this.placeholder();
    }
    if (count === 1) {
      return this.selectedItems()[0].label;
    }
    return `${count} selected`;
  });

  isAllSelected = computed(() => {
    const selectableItems = this.items().filter(item => !item.disabled);
    return selectableItems.length > 0 &&
           this.selectedItems().length === selectableItems.length;
  });

  statsText = computed(() => {
    const selected = this.selectedItems().length;
    const total = this.items().length;
    const shown = this.filteredItems().length;

    if (shown === total) {
      return `${selected} of ${total} selected`;
    }
    return `${selected} of ${total} selected (${shown} shown)`;
  });

  constructor(private elementRef: ElementRef) {}

  // Click outside to close
  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent) {
    const clickedInside = this.elementRef.nativeElement.contains(event.target);
    if (!clickedInside && this.isOpen()) {
      this.close();
    }
  }

  // Keyboard navigation
  @HostListener('document:keydown', ['$event'])
  onKeyDown(event: KeyboardEvent) {
    if (!this.isOpen()) {
      // Open dropdown with Enter or Space
      if ((event.key === 'Enter' || event.key === ' ') &&
          this.elementRef.nativeElement.contains(event.target)) {
        event.preventDefault();
        this.open();
      }
      return;
    }

    switch (event.key) {
      case 'Escape':
        event.preventDefault();
        this.close();
        break;

      case 'ArrowDown':
        event.preventDefault();
        this.highlightNext();
        break;

      case 'ArrowUp':
        event.preventDefault();
        this.highlightPrevious();
        break;

      case 'Enter':
      case ' ':
        event.preventDefault();
        this.toggleHighlighted();
        break;

      case 'Home':
        event.preventDefault();
        this.highlightFirst();
        break;

      case 'End':
        event.preventDefault();
        this.highlightLast();
        break;
    }
  }

  toggle() {
    if (this.disabled() || this.loading()) return;
    this.isOpen() ? this.close() : this.open();
  }

  open() {
    if (this.disabled() || this.loading()) return;
    this.isOpen.set(true);
    this.highlightedIndex.set(-1);

    // Focus search input if searchable
    if (this.searchable()) {
      setTimeout(() => {
        const searchInput = this.elementRef.nativeElement.querySelector('.multiselect-search');
        searchInput?.focus();
      }, 50);
    }
  }

  close() {
    this.isOpen.set(false);
    this.searchQuery.set('');
    this.highlightedIndex.set(-1);
  }

  toggleItem(item: MultiSelectItem, event?: Event) {
    if (event) {
      event.stopPropagation();
    }

    if (item.disabled) return;

    const currentSelections = this.selectedItems();
    const index = currentSelections.findIndex(i => i.value === item.value);

    if (index > -1) {
      // Remove item
      const newSelections = currentSelections.filter(i => i.value !== item.value);
      this.selectedItems.set(newSelections);
      this.selectionChange.emit(newSelections);
    } else {
      // Add item (check max selections)
      const max = this.maxSelections();
      if (max === null || currentSelections.length < max) {
        const newSelections = [...currentSelections, item];
        this.selectedItems.set(newSelections);
        this.selectionChange.emit(newSelections);
      }
    }
  }

  removeBadge(item: MultiSelectItem, event: Event) {
    event.stopPropagation();
    this.toggleItem(item);
  }

  isSelected(item: MultiSelectItem): boolean {
    return this.selectedItems().some(i => i.value === item.value);
  }

  selectAll() {
    const selectableItems = this.filteredItems().filter(item => !item.disabled);
    const max = this.maxSelections();

    const itemsToSelect = max === null
      ? selectableItems
      : selectableItems.slice(0, max);

    this.selectedItems.set(itemsToSelect);
    this.selectionChange.emit(itemsToSelect);
  }

  clearAll() {
    this.selectedItems.set([]);
    this.selectionChange.emit([]);
  }

  onSearchInput(event: Event) {
    const value = (event.target as HTMLInputElement).value;
    this.searchQuery.set(value);
    this.searchChange.emit(value);
    this.highlightedIndex.set(-1);
  }

  clearSearch() {
    this.searchQuery.set('');
    this.highlightedIndex.set(-1);
  }

  // Keyboard navigation helpers
  private highlightNext() {
    const items = this.getSelectableItems();
    if (items.length === 0) return;

    let newIndex = this.highlightedIndex() + 1;
    if (newIndex >= items.length) newIndex = 0;

    this.highlightedIndex.set(newIndex);
    this.scrollToHighlighted();
  }

  private highlightPrevious() {
    const items = this.getSelectableItems();
    if (items.length === 0) return;

    let newIndex = this.highlightedIndex() - 1;
    if (newIndex < 0) newIndex = items.length - 1;

    this.highlightedIndex.set(newIndex);
    this.scrollToHighlighted();
  }

  private highlightFirst() {
    const items = this.getSelectableItems();
    if (items.length > 0) {
      this.highlightedIndex.set(0);
      this.scrollToHighlighted();
    }
  }

  private highlightLast() {
    const items = this.getSelectableItems();
    if (items.length > 0) {
      this.highlightedIndex.set(items.length - 1);
      this.scrollToHighlighted();
    }
  }

  private toggleHighlighted() {
    const items = this.getSelectableItems();
    const index = this.highlightedIndex();

    if (index >= 0 && index < items.length) {
      this.toggleItem(items[index]);
    }
  }

  private getSelectableItems(): MultiSelectItem[] {
    return this.filteredItems().filter(item => !item.disabled);
  }

  private scrollToHighlighted() {
    setTimeout(() => {
      const highlighted = this.elementRef.nativeElement.querySelector('.multiselect-item.highlighted');
      highlighted?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }, 0);
  }

  isItemHighlighted(item: MultiSelectItem): boolean {
    const items = this.getSelectableItems();
    const itemIndex = items.indexOf(item);
    return itemIndex === this.highlightedIndex();
  }
}

import { Component, input, output, signal } from '@angular/core';
import { CommonModule } from '@angular/common';

export interface TabItem {
  id: string;
  label: string;
  content: string;
  disabled?: boolean;
  icon?: string;
}

@Component({
  selector: 'app-tabs',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './tabs.component.html',
  styleUrl: './tabs.component.css'
})
export class TabsComponent {
  // Inputs
  tabs = input.required<TabItem[]>();
  activeTabId = input<string>('');

  // Outputs
  tabChanged = output<TabItem>();

  // State
  activeTab = signal<string>('');

  ngOnInit() {
    // Set initial active tab
    const initialTab = this.activeTabId() || this.tabs()[0]?.id;
    this.activeTab.set(initialTab);
  }

  selectTab(tab: TabItem) {
    if (tab.disabled) {
      return;
    }

    this.activeTab.set(tab.id);
    this.tabChanged.emit(tab);
  }

  isActive(tab: TabItem): boolean {
    return this.activeTab() === tab.id;
  }

  getActiveContent(): string {
    const tab = this.tabs().find(t => t.id === this.activeTab());
    return tab?.content || '';
  }
}

import { Component, input, output, signal, effect } from '@angular/core';
import { CommonModule } from '@angular/common';

export type ToastType = 'success' | 'error' | 'warning' | 'info';
export type ToastPosition = 'top-right' | 'top-left' | 'bottom-right' | 'bottom-left' | 'top-center' | 'bottom-center';

export interface Toast {
  id: string;
  type: ToastType;
  title?: string;
  message: string;
  duration?: number;
  dismissible?: boolean;
}

@Component({
  selector: 'app-toast',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './toast.component.html',
  styleUrl: './toast.component.css'
})
export class ToastComponent {
  // Inputs
  toast = input.required<Toast>();
  position = input<ToastPosition>('top-right');

  // Outputs
  dismissed = output<string>();

  constructor() {
    effect(() => {
      const toastData = this.toast();
      if (toastData && toastData.duration && toastData.duration > 0) {
        setTimeout(() => {
          this.dismiss();
        }, toastData.duration);
      }
    });
  }

  dismiss() {
    this.dismissed.emit(this.toast().id);
  }

  get typeClass(): string {
    const typeMap: Record<ToastType, string> = {
      success: 'toast-success',
      error: 'toast-error',
      warning: 'toast-warning',
      info: 'toast-info'
    };
    return typeMap[this.toast().type];
  }

  get icon(): string {
    const icons: Record<ToastType, string> = {
      success: '✓',
      error: '✕',
      warning: '⚠',
      info: 'ℹ'
    };
    return icons[this.toast().type];
  }
}

