@if (isOpen()) {
  <!-- Backdrop -->
  <div
    class="modal-backdrop"
    (click)="onBackdropClick()"
    [class.loading]="loading()"
  ></div>

  <!-- Modal Container -->
  <div
    class="modal-container"
    [class.modal-centered]="centered()"
    role="dialog"
    [attr.aria-modal]="true"
    [attr.aria-labelledby]="modalId() + '-title'"
    [attr.aria-describedby]="subtitle() ? modalId() + '-subtitle' : null"
  >
    <div
      [class]="dialogClass()"
      (click)="onDialogClick($event)"
      tabindex="-1"
    >
      <!-- Loading Overlay -->
      @if (loading()) {
        <div class="modal-loading-overlay">
          <svg class="spinner spinner-lg" viewBox="0 0 24 24">
            <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4" fill="none"></circle>
            <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
        </div>
      }

      <!-- Header -->
      @if (showHeader() && (title() || showCloseButton() || variant() !== 'default')) {
        <div class="modal-header">
          <div class="modal-header-content">
            @if (variant() !== 'default') {
              <div class="modal-variant-icon" [style.color]="getVariantColor()">
                <span class="modal-variant-icon-text">{{ getVariantIcon() }}</span>
              </div>
            }
            <div class="modal-title-container">
              @if (title()) {
                <h2 class="modal-title" [id]="modalId() + '-title'">
                  {{ title() }}
                </h2>
              }
              @if (subtitle()) {
                <p class="modal-subtitle" [id]="modalId() + '-subtitle'">
                  {{ subtitle() }}
                </p>
              }
            </div>
          </div>
          @if (showCloseButton()) {
            <button
              type="button"
              class="modal-close"
              (click)="close()"
              [disabled]="loading()"
              aria-label="Close modal"
            >
              <svg class="modal-close-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
              </svg>
            </button>
          }
        </div>
      }

      <!-- Body -->
      <div class="modal-body" [class.scrollable]="scrollable()">
        <ng-content></ng-content>
      </div>

      <!-- Footer -->
      @if (showFooter()) {
        <div class="modal-footer">
          <ng-content select="[modal-footer]"></ng-content>
        </div>
      }
    </div>
  </div>
}

